package io.xeros.solo;
import io.xeros.*;import io.xeros.content.achievement_diary.*;import io.xeros.content.achievement_diary.impl.*;import io.xeros.content.skills.herblore.*;import io.xeros.content.skills.smithing.AnvilRecipes;import io.xeros.content.skills.fletching.FletchingRecipes;import io.xeros.content.questing.CooksAssistant;import io.xeros.model.entity.player.*;import io.xeros.model.items.*;import java.util.*;
@SuppressWarnings({"rawtypes","unchecked"})public class DiaryProduction70Check {
 static void ok(boolean b,String m){if(!b)throw new AssertionError(m);}static void clear(Player p){p.interruptActions();Arrays.fill(p.playerItems,0);Arrays.fill(p.playerItemsN,0);}
 static void potion(Player p,int id,int x,int y,StatefulAchievementDiary diary,Enum entry){clear(p);BossRoutesCheck.at(p,x,y,0);PotionData.FinishedPotions r=Arrays.stream(PotionData.FinishedPotions.values()).filter(v->v.getResult().getId()==id).findFirst().orElseThrow();GameItem base=r.getPrimary();p.getItems().addItem(base.getId(),base.getAmount());for(GameItem item:r.getIngredients())p.getItems().addItem(item.getId(),item.getAmount());int before=diary.getAbsoluteAchievementStage(entry);ok(new Herblore(p).mix(base.getId()),"Mix "+id);SkillsAuditCheck.tick(4);ok(diary.getAbsoluteAchievementStage(entry)==before+1&&p.getItems().getInventoryCount(id)>0,"Missing native potion diary "+entry);}
 static void smith(Player p,int id,int x,int y,StatefulAchievementDiary diary,Enum entry){clear(p);BossRoutesCheck.at(p,x,y,0);AnvilRecipes.Recipe r=AnvilRecipes.forProduct(id);p.getItems().addItem(2347,1);p.getItems().addItem(r.bar,r.bars);int before=diary.getAbsoluteAchievementStage(entry);ok(AnvilRecipes.make(p,id,1),"Smith "+id);SkillsAuditCheck.tick(6);ok(diary.getAbsoluteAchievementStage(entry)==before+1&&p.getItems().getInventoryCount(id)>0,"Missing native smith diary "+entry);}
 static void fletch(Player p,int id,int x,int y,StatefulAchievementDiary diary,Enum entry){clear(p);BossRoutesCheck.at(p,x,y,0);FletchingRecipes.Recipe r=FletchingRecipes.recipes().stream().filter(v->v.product==id).findFirst().orElseThrow();p.getItems().addItem(r.first,1);if(r.second>0)p.getItems().addItem(r.second,1);if(r.tool>0)p.getItems().addItem(r.tool,1);int before=diary.getAbsoluteAchievementStage(entry);ok(FletchingRecipes.make(p,r,1),"Fletch "+id);SkillsAuditCheck.tick(r.ticks+1);ok(diary.getAbsoluteAchievementStage(entry)==before+1&&p.getItems().getInventoryCount(id)>0,"Missing native fletching diary "+entry);}
 public static void main(String[]args)throws Exception{Thread.setDefaultUncaughtExceptionHandler((t,e)->{e.printStackTrace();System.exit(1);});Thread.currentThread().setName("GameThread");System.setProperty("solo.mode","true");System.setProperty("solo.xp","1");Server.startServerless();Player p=ClassicQuests70Check.actor();AchievementDiaryManager d=p.getDiaryManager();potion(p,12695,2612,3275,d.getArdougneDiary(),ArdougneDiaryEntry.SUPER_COMBAT_ARD);ok(d.getVarrockDiary().getAbsoluteAchievementStage(VarrockDiaryEntry.SUPER_COMBAT)==1,"Super combat global recipe");potion(p,9741,3300,3050,d.getDesertDiary(),DesertDiaryEntry.COMBAT_POTION);potion(p,163,2650,3650,d.getFremennikDiary(),FremennikDiaryEntry.MIX_SUPER_DEFENCE);potion(p,5940,2800,3440,d.getKandarinDiary(),KandarinDiaryEntry.WEAPON_POISON_PLUS_PLUS);potion(p,12905,2750,3200,d.getKaramjaDiary(),KaramjaDiaryEntry.ANTI_VENOM);
 smith(p,865,3187,3425,d.getVarrockDiary(),VarrockDiaryEntry.SMITH_STEEL_KNIFES);smith(p,868,3187,3425,d.getVarrockDiary(),VarrockDiaryEntry.SMITH_RUNE_KNIFES);smith(p,1127,3187,3425,d.getLumbridgeDraynorDiary(),LumbridgeDraynorDiaryEntry.RUNE_PLATE_LUM);smith(p,1355,3187,3930,d.getWildernessDiary(),WildernessDiaryEntry.SMITH_MITHRIL_AXE);smith(p,1331,3187,3930,d.getWildernessDiary(),WildernessDiaryEntry.SMITH_ADAMANT_SCIMITAR);smith(p,1333,3187,3930,d.getWildernessDiary(),WildernessDiaryEntry.SMITH_RUNE_SCIM_WILD);fletch(p,70,2800,3440,d.getKandarinDiary(),KandarinDiaryEntry.FLETCH_MAGIC_BOW);fletch(p,54,2420,3440,d.getWesternDiary(),WesternDiaryEntry.FLETCH_OAK_SHORT_WEST);
 clear(p);BossRoutesCheck.at(p,3101,3509,0);DiaryProduction.potion(p,5940);ok(d.getKandarinDiary().getAbsoluteAchievementStage(KandarinDiaryEntry.WEAPON_POISON_PLUS_PLUS)==1,"Wrong-location poison progress");AnvilRecipes.make(p,865,1);SkillsAuditCheck.tick(6);ok(d.getVarrockDiary().getAbsoluteAchievementStage(VarrockDiaryEntry.SMITH_STEEL_KNIFES)==1,"Failed smith gave progress");ok(!CooksAssistant.rangeAllowed(p,114),"Cook range before quest");ClassicQuests70Check.quest(p,"Cook's Assistant").setStage(8);BossRoutesCheck.at(p,3212,3216,0);ok(CooksAssistant.rangeAllowed(p,114)&&CooksAssistant.burnLevel(p,317,114,34)==31&&CooksAssistant.burnLevel(p,19656,114,84)==52&&CooksAssistant.burnLevel(p,21684,114,89)==60&&CooksAssistant.burnLevel(p,317,7183,34)==34,"Cook range reward thresholds");System.out.println("ALL_14_RESTORED_DIARY_NATIVE_PRODUCTION_TRANSACTIONS_REGION_GUARDS_FAILED_RECIPE_NO_PROGRESS_AND_COOK_RANGE_UNLOCK_PASS");System.exit(0);}
}